// TypeScript interfaces for OOTDay Fashion Assistant

// Export all new type definitions
export * from './types/enums'
export * from './types/localization-types'
export * from './types/product-types'

// Re-export FlatLayItem from image-types for use in ChatMessage
import type { FlatLayItem } from './types/image-types'
export type { FlatLayItem }

// Legacy interfaces maintained for backward compatibility
// These will gradually be replaced by EnhancedProduct
export interface OutfitRequest {
  query: string
  userId?: string
  context?: {
    occasion?: string
    weather?: string
    preferences?: string[]
  }
}

export interface OutfitResponse {
  outfits: Outfit[]
  conversationId: string
  suggestions: string[]
}

export interface Outfit {
  id: string
  title: string
  description: string
  totalPrice: number
  items: Product[]
  imageUrl?: string
  /** Flat-lay image URL for outfit visualization (v5.0) */
  flatLayImageUrl?: string
  /** Flat-lay image as base64 fallback (v5.0) */
  flatLayImageBase64?: string
  /** Flag indicating flat-lay image is being generated (v5.0) */
  isGeneratingFlatLay?: boolean
}

/**
 * @deprecated Use EnhancedProduct from './types/product-types' instead
 * This interface is kept for backward compatibility
 */
export interface Product {
  sku: string
  name: string
  brand: string
  price: number
  imageUrl: string
  availability: "in_stock" | "low_stock" | "out_of_stock"
  storeLocations?: string[]
  onlineUrl?: string
  sizes?: string[]
  colors?: string[]
  category?: string // "Men", "Women", or other categories
  subCategory?: string // "Blazer", "Skirt", "Pants", etc.
  visualDescription?: string // For AI Image Generation prompt
  occasion?: string[] // For filtering
}

export interface ChatMessage {
  id: string
  content: string
  sender: "user" | "assistant"
  timestamp: Date
  outfits?: Outfit[]
  /** Image URL for generated outfit visualization (v3.1) */
  imageUrl?: string
  /** Base64-encoded image data (v3.1) */
  imageBase64?: string
  /** Outfit description used for image generation (v3.1) */
  outfitDescription?: string
  /** Image display mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) (v4.0) */
  displayMode?: 'portrait' | 'flat-lay'
  /** Recommended items for flat-lay display (v4.0) */
  recommendedItems?: FlatLayItem[]
}

export interface ConversationStarter {
  id: string
  text: string
  category: string
}

export interface FilterState {
  gender?: 'all' | 'men' | 'women'
  occasion?: string[]  // ['work', 'casual', 'date', 'formal']
  priceRange?: { min: number; max: number }
  searchQuery?: string
}

/**
 * Type definitions for image generation feature (Customer Journey Step 4)
 * Supports text-to-image generation for outfit visualization using OpenRouter's Gemini 2.5 Flash Image model
 */

/**
 * Individual item in a flat-lay composition
 */
export interface FlatLayItem {
  /** Product name */
  name: string;
  /** Product category (e.g., 'Dress', 'Shoes') */
  category: string;
  /** Product color for prompt accuracy */
  color?: string;
  /** Optional detailed visual description */
  visualDescription?: string;
}

/**
 * Request payload for flat-lay image generation
 */
export interface FlatLayRequest {
  /** Array of recommended products */
  items: FlatLayItem[];
  /** Total item count for display */
  totalItems?: number;
  /** Optional occasion context (e.g., 'work outfit') */
  occasionContext?: string;
}

/**
 * Request payload for image generation API
 */
export interface ImageGenerationRequest {
  /** Description of the outfit to generate (fashion context extracted from conversation) */
  description: string;
  /** Optional style parameters for image generation */
  style?: {
    /** Photography style: 'professional', 'casual', 'studio', 'lifestyle' */
    photographyStyle?: string;
    /** Composition: 'full-body', 'flat-lay', 'mannequin', '3/4-view' */
    composition?: string;
    /** Lighting mood: 'natural', 'studio', 'soft', 'bright' */
    lighting?: string;
    /** Cultural context: 'thai-contemporary', 'minimalist', 'classic', 'modern' */
    aestheticContext?: string;
  };
  /**
   * Base64-encoded reference image for multimodal generation.
   * Must include data URL prefix (e.g., 'data:image/jpeg;base64,...').
   * Used for fitting model generation to enable accurate face-matching.
   */
  referenceImage?: string;
  /**
   * Type of image generation to perform.
   * - 'outfit': Standard outfit image generation (default)
   * - 'fitting-model': Fitting model generation with reference image for face-matching
   * - 'flat-lay': Flat-lay composition of recommended items
   */
  generationType?: 'outfit' | 'fitting-model' | 'flat-lay';
  /**
   * Items for flat-lay generation (required when generationType is 'flat-lay')
   */
  flatLayItems?: FlatLayItem[];
  /**
   * Occasion context for flat-lay generation
   */
  occasionContext?: string;
}

/**
 * Response from image generation API
 */
export interface ImageGenerationResponse {
  /** URL to the generated image (if hosted) */
  imageUrl?: string;
  /** Base64-encoded image data (if returned inline) */
  imageBase64?: string;
  /** Metadata about the generated image */
  metadata?: {
    /** Model used for generation */
    model: string;
    /** Generation timestamp */
    generatedAt: string;
    /** Prompt used for generation */
    prompt?: string;
    /** Image dimensions */
    dimensions?: {
      width: number;
      height: number;
    };
  };
  /** Error message if generation failed */
  error?: string;
  /** User-friendly message for display */
  message?: string;
  /** Success flag */
  success: boolean;
}

/**
 * Props for LooksInspiration UI component
 */
export interface LooksInspirationProps {
  /** Outfit description used for generation */
  outfitDescription: string;
  /** URL to generated image */
  imageUrl?: string;
  /** Base64-encoded image data */
  imageBase64?: string;
  /** Loading state for image generation */
  isLoading?: boolean;
  /** Error message if generation failed */
  error?: string;
  /** Callback for retry button */
  onRetry?: () => void;
  /** Optional callback for "generate another" functionality */
  onGenerateAnother?: () => void;
  /** Optional callback for download functionality */
  onDownload?: () => void;
  /** Layout mode: 'portrait' (3:4) or 'flat-lay' (1:1 square) */
  displayMode?: 'portrait' | 'flat-lay';
  /** Items to display in flat-lay mode */
  recommendedItems?: FlatLayItem[];
  /** Optional custom header title */
  headerTitle?: string;
}

/**
 * Internal state for image generation in chat
 */
export interface ImageGenerationState {
  /** Whether image is currently being generated */
  isGenerating: boolean;
  /** Generated image URL */
  imageUrl?: string;
  /** Generated image base64 data */
  imageBase64?: string;
  /** Outfit description used for generation */
  outfitDescription?: string;
  /** Error message */
  error?: string;
}

